using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Drawing;

sealed partial class Companion {

 internal string CaptureCollection(){string folder=CaptureRoot,id="r"+Program.Hash(folder.ToLowerInvariant()).Substring(0,12).ToLowerInvariant();var list=new List<object>();foreach(string file in SafeFiles(folder,"*",0).Where(f=>new[]{".png",".jpg",".jpeg",".mp4"}.Contains(Path.GetExtension(f).ToLowerInvariant())).Take(60000)){string relative=file.Substring(folder.Length+1).Replace('\\','/');var info=new FileInfo(file);list.Add(new{id=id+":"+relative,name=info.Name,type=Path.GetExtension(file).Equals(".mp4",StringComparison.OrdinalIgnoreCase)?"video":"image",rootId=id,relativePath=relative,url="https://"+id+".jagolibrary.example/"+String.Join("/",relative.Split('/').Select(Uri.EscapeDataString)),size=info.Length,stamp=info.LastWriteTimeUtc.Ticks.ToString()+":"+info.Length,tags=new[]{"Companion capture"}});}string collection=Path.Combine(store.Home,".jago","Companion captures.jagolibrary");Store.Atomic(collection,Store.Json.Serialize(new{version=1,name="Companion captures",roots=new[]{new{id=id,path=folder,name="Companion captures"}},assets=list,recipes=new object[0],layout=new{width=1080,height=1080,background="#f8f6f0",layers=new object[0]}}));return collection;}

 internal static IEnumerable<string> SafeFiles(string folder,string pattern,int depth){if(depth>8||(File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0)yield break;foreach(string file in Directory.GetFiles(folder,pattern))if((File.GetAttributes(file)&FileAttributes.ReparsePoint)==0)yield return file;foreach(string child in Directory.GetDirectories(folder))foreach(string file in SafeFiles(child,pattern,depth+1))yield return file;}


 internal string FindLibrary(){var candidates=new List<string>();string local=AppDomain.CurrentDomain.BaseDirectory;foreach(string path in new[]{Path.Combine(local,"Jago-Library.exe"),Path.Combine(local,"..","Library-Production","Jago-Library.exe"),Path.Combine(local,"..","Library","Jago-Library.exe")})candidates.Add(path);try{var paths=Store.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(Shared,"connections.json")));string stored;if(paths.TryGetValue("library",out stored))candidates.Insert(0,stored);}catch{}foreach(string channel in new[]{"Preview","Installed"})try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Jago Suite\"+channel+@"\Components\library"))if(key!=null)candidates.Add(Convert.ToString(key.GetValue("Executable")));}catch{}return candidates.Where(ValidLibrary).OrderByDescending(x=>{var i=FileVersionInfo.GetVersionInfo(x);return new Version(i.FileMajorPart,i.FileMinorPart,i.FileBuildPart);}).FirstOrDefault();}
 internal bool ValidLibrary(string path){if(String.IsNullOrEmpty(path)||!File.Exists(path)||!Path.GetExtension(path).Equals(".exe",StringComparison.OrdinalIgnoreCase))return false;try{string name=FileVersionInfo.GetVersionInfo(path).ProductName;return name=="Jago Library + Production Studio"||name=="Jago Library";}catch{return false;}}
 internal void OpenCapturesLibrary(){try{string exe=FindLibrary();if(exe==null){using(var f=Dialog("Open captures in Library",500,280)){f.Controls.Add(new System.Windows.Forms.Label{Text="Your capture is saved in "+CaptureRoot+". Library is optional. Locate its app if you have it, or open the folder directly.",Dock=System.Windows.Forms.DockStyle.Fill});var row=new System.Windows.Forms.FlowLayoutPanel{Dock=System.Windows.Forms.DockStyle.Bottom,Height=55};var locate=new System.Windows.Forms.Button{Text="Locate Library…",AutoSize=true};locate.Click+=(s,e)=>{using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Choose Jago Library",Filter="Jago Library (*.exe)|*.exe"})if(picker.ShowDialog(f)==System.Windows.Forms.DialogResult.OK){if(!ValidLibrary(picker.FileName)){System.Windows.Forms.MessageBox.Show(f,"Choose the Jago Library app.","Library not recognised");return;}exe=picker.FileName;f.Close();}};row.Controls.Add(locate);var folder=new System.Windows.Forms.Button{Text="Open folder",AutoSize=true};folder.Click+=(s,e)=>{Open(CaptureRoot);f.Close();};row.Controls.Add(folder);var cancel=new System.Windows.Forms.Button{Text="Cancel",AutoSize=true,DialogResult=System.Windows.Forms.DialogResult.Cancel};row.Controls.Add(cancel);f.Controls.Add(row);ThemeControls(f);f.ShowDialog(this);}if(exe==null)return;}
 var info=FileVersionInfo.GetVersionInfo(exe);if(new Version(info.FileMajorPart,info.FileMinorPart,info.FileBuildPart)>=new Version(0,10,1)){var launch=new ProcessStartInfo(exe,"--companion-captures "+Quote(CaptureRoot)){UseShellExecute=false};foreach(string key in new[]{"JAGO_WORKSPACE_ROOT","JAGO_WORKSPACE_TAB_ROOT","JAGO_WORKSPACE_TAB_ID"})launch.EnvironmentVariables.Remove(key);launch.EnvironmentVariables["JAGO_SUITE_ROOT"]=Shared;Process.Start(launch);Tell("Captures opened in Library without replacing its project.");}else{string collection=CaptureCollection();if(System.Windows.Forms.MessageBox.Show(this,"This Library version opens captures as a separate collection. Save its current project first, or update to the capture-inbox preview. Open the collection?","Open captures",System.Windows.Forms.MessageBoxButtons.OKCancel)!=System.Windows.Forms.DialogResult.OK)return;Process.Start(new ProcessStartInfo(exe,Quote(collection)){UseShellExecute=false});}
 string file=Path.Combine(Shared,"connections.json");var connections=File.Exists(file)?Store.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(file)):new Dictionary<string,string>();connections["library"]=exe;Store.Atomic(file,Store.Json.Serialize(connections));}catch(Exception e){Tell("Library connection: "+e.Message);}}
}
